const nav = document.getElementById('tableNav');
const dictionary = document.getElementById('dictionary');
const search = document.getElementById('search');
const resultCount = document.getElementById('resultCount');
const slug = name => 'tabela_' + name;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function tagMarkup(tags){return tags.length?tags.map(t=>`<span class="tag">[${esc(t)}]</span>`).join(' '):'<span class="muted">—</span>';}
function privacyMarkup(value){const cls=value==='DPS'?'tag-DPS':value==='DP'?'tag-DP':'tag-NA';return `<span class="tag ${cls}">[${value==='N/A'?'N/A':esc(value)}]</span>`;}
function render(query=''){
 const q=query.trim().toLowerCase(); let shown=0, cols=0;
 nav.innerHTML=''; dictionary.innerHTML='';
 schema.forEach(table=>{
  const filtered=table.columns.filter(c=>!q||table.name.toLowerCase().includes(q)||c.name.toLowerCase().includes(q)||c.desc.toLowerCase().includes(q));
  if(q&&!table.name.toLowerCase().includes(q)&&filtered.length===0)return;
  shown++; cols+=filtered.length;
  const link=document.createElement('a');link.href='#'+slug(table.name);link.textContent=table.name;nav.appendChild(link);
  const section=document.createElement('section');section.className='table-card';section.id=slug(table.name);
  const rows=filtered.map(c=>`<tr><td><code>${esc(c.name)}</code></td><td>${esc(c.desc)}<div class="muted">Padrão: ${esc(c.default)}</div></td><td><code>${esc(c.type)}</code></td><td>${tagMarkup(c.tags)}</td><td>${privacyMarkup(c.privacy)}</td><td>${esc(c.lineage)}</td><td>${esc(c.rbac)}</td></tr>`).join('');
  section.innerHTML=`<div class="table-heading"><h2>${esc(table.name)}</h2><p>${esc({"perfil": "Define papéis e níveis de acesso utilizados no controle RBAC.", "permissao": "Catálogo de permissões ou funcionalidades controláveis pelo RBAC.", "perfil_permissao": "Associação entre perfis e permissões; implementa a relação muitos-para-muitos.", "usuario": "Contas de operadores e supervisores, com autenticação e vínculo a perfil.", "log_auditoria": "Registra operações auditáveis, valores anteriores/novos, contexto de origem e usuário relacionado.", "endereco": "Armazena dados de endereço normalizados de parceiros comerciais.", "fabricante": "Cadastro de fabricantes e sua identificação comercial e endereço.", "fornecedor": "Cadastro de fornecedores vinculados às notas fiscais de entrada.", "setor": "Agrupa categorias do catálogo comercial.", "categoria": "Classifica produtos e está vinculada a um setor.", "produto": "Cadastro de itens comercializados, preços, estoque e classificação fiscal.", "historico_preco": "Histórico de alterações de preço de produtos, associado ao usuário responsável.", "forma_pagamento": "Modalidades de pagamento aceitas e parâmetros relacionados.", "pedido": "Cabeçalho da venda, com data, consumidor opcional, status e operador responsável.", "item_pedido": "Itens associados a um pedido, preservando quantidade, preço praticado e desconto.", "pagamento_pedido": "Detalhamento de cada forma de pagamento utilizada no pedido.", "nota_fiscal_entrada": "Cabeçalho de documento fiscal de entrada importado de fornecedor.", "item_nota_fiscal": "Produtos e valores unitários discriminados em uma nota fiscal de entrada.", "estorno": "Registro de estorno/cancelamento associado ao pedido e ao usuário autorizador."}[table.name])}</p></div><div class="table-responsive"><table class="dictionary-table"><thead><tr><th>Atributo</th><th>Descrição / Regra de Negócio</th><th>Tipo e Tamanho</th><th>Constraints</th><th>Privacidade (LGPD/GDPR)</th><th>Linhagem (Data Lineage)</th><th>Controle de Acesso (RBAC)</th></tr></thead><tbody>${rows||'<tr><td colspan="7">Nenhuma coluna corresponde à pesquisa.</td></tr>'}</tbody></table></div>`;
  dictionary.appendChild(section);
 });
 resultCount.textContent=`${shown} de ${schema.length} tabelas · ${cols} colunas exibidas`;
}
search.addEventListener('input',e=>render(e.target.value));
document.getElementById('themeToggle').addEventListener('click',()=>document.body.classList.toggle('dark'));
const modal=document.getElementById('derModal'), viewport=document.getElementById('derViewport'), img=document.getElementById('derImage');
let panzoomInstance=null;
document.getElementById('openDer').addEventListener('click',()=>{modal.hidden=false;document.body.style.overflow='hidden';if(window.Panzoom&&!panzoomInstance){panzoomInstance=Panzoom(img,{maxScale:8,minScale:.2,contain:'outside'});viewport.addEventListener('wheel',panzoomInstance.zoomWithWheel);}});
function closeModal(){modal.hidden=true;document.body.style.overflow='';}
document.getElementById('closeDer').addEventListener('click',closeModal);
modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});
document.getElementById('zoomIn').addEventListener('click',()=>panzoomInstance?.zoomIn());
document.getElementById('zoomOut').addEventListener('click',()=>panzoomInstance?.zoomOut());
document.getElementById('resetZoom').addEventListener('click',()=>panzoomInstance?.reset());
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.hidden)closeModal();});
render();
